    // --- UI 交互控制逻辑 ---
    function handleIdentityChange() {
        const identity = document.getElementById('identity').value;
        const customInput = document.getElementById('identity_custom');
        const panelNormal = document.getElementById('panel_normal');
        const panelFood = document.getElementById('panel_food');
        const locSelect = document.getElementById('location');

        // 处理自定义输入框
        if (identity === '自定义') {
            customInput.classList.remove('hidden');
        } else {
            customInput.classList.add('hidden');
        }

        // 处理专属面板显示
        if (identity === '待食用人') {
            panelNormal.classList.add('hidden');
            panelFood.classList.remove('hidden');
        } else if (identity === '普通公民' || identity === '黑市顾客' || identity === '自定义') {
            panelFood.classList.add('hidden');
            panelNormal.classList.remove('hidden');
        } else {
            panelNormal.classList.add('hidden');
            panelFood.classList.add('hidden');
        }

        // 动态处理位置选项中的“肉店公开饲养间内”
        let specialOption = Array.from(locSelect.options).find(opt => opt.value === '肉店公开饲养间内');
        if (identity === '待食用人') {
            if (!specialOption) {
                let opt = document.createElement('option');
                opt.value = '肉店公开饲养间内';
                opt.text = '肉店公开饲养间内';
                locSelect.add(opt, locSelect.options[locSelect.options.length - 1]);
            }
        } else {
            if (specialOption) {
                if(locSelect.value === '肉店公开饲养间内') {
                    locSelect.value = '';
                }
                locSelect.removeChild(specialOption);
            }
        }
    }

    function handleCustomInput(selectId, inputId) {
        const select = document.getElementById(selectId);
        const input = document.getElementById(inputId);
        if (select.value === '自定义') {
            input.classList.remove('hidden');
        } else {
            input.classList.add('hidden');
        }
    }

    function rollDice(selectId) {
        const select = document.getElementById(selectId);
        const options = select.options;
        let validIndices = [];
        for (let i = 0; i < options.length; i++) {
            if (!options[i].disabled && i !== select.selectedIndex) {
                validIndices.push(i);
            }
        }

        if (validIndices.length > 0) {
            const randomIndex = validIndices[Math.floor(Math.random() * validIndices.length)];
            select.selectedIndex = randomIndex;
            select.dispatchEvent(new Event('change'));
        }
    }

    // --- 数据收集与内容生成逻辑 ---

    // 映射黑市想法到黑市身份
    function mapThoughtsToMarketIdentity(thoughts) {
        switch(thoughts) {
            case '那是咱老家！': return '黑市常客';
            case '我只是刚来': return '黑市入门新人';
            case '我不造啊……？但是哪里有点怪怪的……': return '黑市潜在客户';
            case '这是啥地方？': return '尚未得知黑市存在';
            default: return thoughts; // 自定义内容直接返回
        }
    }

    // 映射肉质潜力选项到正式人设词条
    function mapMeatPotential(potential) {
        switch(potential) {
            case '大有前途': return '大有前途';
            case '中等偏上': return '中等偏上';
            case '中规中矩': return '中规中矩';
            case '有点勉强……': return '中等偏下';
            case '依托': return '毫无潜力';
            case '……我不打算': return '无被食意愿';
            default: return potential;
        }
    }

    // 获取实际输入值（处理自定义项）
    function getActualValue(selectId, customId) {
        const selectVal = document.getElementById(selectId).value;
        if (selectVal === '自定义' && customId) {
            return document.getElementById(customId).value || '未填写';
        }
        return selectVal || '未选择';
    }

    // 修改开始按钮的绑定事件，原 html 中的 onclick="alert('...')" 需要改为 onclick="startStory()"
    // 如果哥哥不想改 html，可以在这里通过 JS 强行绑定
    document.addEventListener('DOMContentLoaded', () => {
        const startBtn = document.querySelector('.start-btn');
        if (startBtn) {
            startBtn.onclick = startStory;
        }
    });

    async function startStory() {
        const startBtn = document.querySelector('.start-btn');

        // 检查按钮是否已经被禁用，如果是，直接退出，防止连发
        if (startBtn && startBtn.disabled) {
            return;
        }

        // 锁上按钮：禁用点击，改变鼠标指针状态
        if (startBtn) {
            startBtn.disabled = true;
            startBtn.style.pointerEvents = 'none';
            startBtn.style.opacity = '0.7'; // 稍微变暗一点提示处于冷却状态
        }

        // 1. 收集身份信息
        const identity = getActualValue('identity', 'identity_custom');
        if (identity === '未选择') {
            alert('请先选择你的身份！');
            // 如果报错返回，需要立刻解锁按钮
            if (startBtn) {
                startBtn.disabled = false;
                startBtn.style.pointerEvents = 'auto';
                startBtn.style.opacity = '1';
            }
            return;
        }

        // 2. 收集位置与想法
        const location = getActualValue('location', 'location_custom');
        const rawThoughts = getActualValue('thoughts', 'thoughts_custom');
        const marketIdentity = mapThoughtsToMarketIdentity(rawThoughts);

        // 3. 构建基础设定文本
        let settingText = `<{{user}}基础设定>\n身份：${identity}\n`;

        if (identity === '待食用人') {
            const app = document.getElementById('grade_appearance').value;
            const mus = document.getElementById('grade_muscle').value;
            const fat = document.getElementById('grade_fat').value;
            const acid = document.getElementById('grade_acid').value;

            settingText += `总体外貌评级：${app}\n肌肉分布评级：${mus}\n脂肪评级：${fat}\n乳酸检测评级：${acid}\n`;

            if (app === 'A' && mus === 'A' && fat === 'A' && acid === 'A') {
                settingText += `总评：S\n`;
            }
        } else {
            const tKill = document.getElementById('tech_kill').value;
            const tFeed = document.getElementById('tech_feed').value;
            const rawMPot = document.getElementById('meat_potential').value;
            const mPot = mapMeatPotential(rawMPot);

            settingText += `屠宰技术：${tKill}\n饲养技术：${tFeed}\n肉质潜力：${mPot}\n`;
        }

        settingText += `黑市身份：${marketIdentity}\n</{{user}}基础设定>`;

        // 4. 尝试写入世界书 (基于酒馆助手 API 修复版)
        try {
            const worldbookName = '做人，要讲究火候';
            // 获取 TavernHelper API
            const TH = window.parent.TavernHelper || window.TavernHelper || window;

            if (typeof TH.getWorldbook === 'function') {
                // 获取目标世界书的现有条目
                const entries = await TH.getWorldbook(worldbookName);

                // 注意：酒馆助手 API 中条目的名称字段是 name，而不是 comment
                const existingEntry = entries.find(e => e.name === 'user设定');

                if (existingEntry) {
                    // 如果已存在，则只更新该条目的内容，保留哥哥手动设置好的其他配置
                    await TH.updateWorldbookWith(worldbookName, (wb) => {
                        const target = wb.find(e => e.name === 'user设定');
                        if (target) {
                            target.content = settingText;
                            // 确保关键字里包含需要触发的词
                            target.keys = ['{{user}}', '设定', '基础设定'];
                        }
                        return wb;
                    });
                    console.log('世界书条目更新成功');
                } else {
                    // 如果万一不存在，进行新建。这里尽量补全基本字段，防止继承错误设置
                    await TH.createWorldbookEntries(worldbookName, [{
                        name: 'user设定',
                        content: settingText,
                        keys: ['{{user}}', '设定', '基础设定'],
                        insertion_order: 0, // 插入顺序
                        case_sensitive: false, // 区分大小写
                        constant: false, // 是否始终开启
                        probability: 100 // 触发概率
                    }]);
                    console.log('世界书条目创建成功');
                }
            } else {
                console.log('未检测到酒馆助手 API，跳过世界书写入。');
            }
        } catch (e) {
            console.error('世界书写入失败:', e);
        }



        // 5. 拼装发给 AI 的最终指令
        const promptCommand = `${settingText}
以上是{{user}}的基础设定。
当前情境：{{user}}正身处于【${location}】。
系统指令：请根据当前的时间、地点以及{{user}}的设定，随机生成并描写周围的NPC、场景设施（如肉店、饲养笼等）或一切可能发生的环境变化。请务必保持非全知的客观叙事视角，通过感官细节呈现氛围。
【强制规则】：
- {{user}}周围出现的待食用人必须为女性。
- 场景中出现的黑市/饲养/屠宰从业人员必须为女性。
- 仅有“加工贩卖”环节的普通从业者性别可男可女。`;

        // 6. 触发发送
        const commands = [
            `/send ${promptCommand}`,
            `/trigger`
        ];

        try {
            const originalText = startBtn ? startBtn.textContent : '开始故事！';
            if (startBtn) startBtn.textContent = '正在进入世界...';

            await triggerSlash(commands.join(' | '));

            // 一秒冷却后恢复按钮状态并解锁
            setTimeout(() => {
                if (startBtn) {
                    startBtn.textContent = originalText;
                    startBtn.disabled = false;
                    startBtn.style.pointerEvents = 'auto';
                    startBtn.style.opacity = '1';
                }
            }, 1000);

        } catch (error) {
            console.error('发送指令失败:', error);
            alert('指令发送出现问题，请检查后台连接。');

            // 发生错误时立刻解锁
            if (startBtn) {
                startBtn.disabled = false;
                startBtn.style.pointerEvents = 'auto';
                startBtn.style.opacity = '1';
            }
        }
    }

</script>
